SELECT COUNT(*)             AS pv,
       COUNT(DISTINCT user) AS uv,
       COUNT(DISTINCT ip)   AS uip
FROM t_link_access_logs
WHERE full_short_url = #{fullShortUrl}
  AND gid = #{gid}
  AND del_flag = 0
  AND create_time BETWEEN #{startDate} AND #{endDate}
GROUP BY full_short_url, gid

SELECT ip,
       COUNT(ip) AS count
FROM t_link_access_logs
WHERE full_short_url = #{fullShortUrl}
  AND gid = #{gid}
  AND del_flag = 0
  AND create_time BETWEEN #{startDate} AND #{endDate}
GROUP BY full_short_url, gid, ip
ORDER BY count DESC
LIMIT 5

SELECT user, IF(MIN(create_time) BETWEEN CONCAT(#{startDate},' 00:00:00') AND CONCAT(#{endDate},' 23:59:59'), '新访客', '老访客') AS uvType FROM t_link_access_logs WHERE full_short_url = #{fullShortUrl} AND gid = #{gid} AND user IN
#{item}
GROUP BY user

SELECT user, IF(MIN(create_time) BETWEEN #{startDate} AND #{endDate}, '新访客', '老访客') AS uvType FROM t_link_access_logs WHERE gid = #{gid} AND user IN
#{item}
GROUP BY user
